@Injectable()
export class LoggingInterceptor
        implements NestInterceptor {

    intercept(
        context: ExecutionContext,
        next: CallHandler
    ) {
        const start =
            Date.now();

        return next
            .handle()
            .pipe(
                tap(() =>
                    console.log(
                        `Took ${
                            Date.now() - start
                        }ms`
                    )
                )
            );
    }
}

